      "× ダイナミック・ケイパビリティ論は、RBV（リソース・ベースト・ビュー）が静態的であるという批判を踏まえ、不確実な環境下でいかに内部・外部の経営資源を再構成し持続的競争優位を築くかを解明した理論です。"
