    "36協定における時間外労働の限度時間は、原則として「月45時間・年360時間」であり、臨時的な特別の事情がない限りこれを超えることはできない。",
    "特別条項付き36協定を締結すれば、1年を通じて毎月100時間以上の時間外労働を行わせることが法的に認められる。",
