  "explanation": "【購買前後の心理メカニズム】\n・購買前：知覚リスク（リスクを減らすため、有名ブランド選び、口コミ調査、返品保証を求める）\n・購買後：認知的不協和（購入決定後の不安・後悔。アフターフォローで解消しリピートにつなげる）",
